
(function(){
'use strict';
const ATLAS={'fuji_rope_95':'data:image/jpeg;base64,','cindy_0':'data:image/jpeg;base64,','cindy_2':'data:image/jpeg;base64,','cindy_1':'data:image/jpeg;base64,'};
const NAMES={'fuji_rope_95':'Скакалка','cindy_0':'Подтягивания','cindy_1':'Отжимания','cindy_2':'Приседания'};
const previousRender=renderExMediaGrid;
renderExMediaGrid=function(){
 previousRender();
 const grid=document.getElementById('exMediaGrid');
 if(!grid||!Object.prototype.hasOwnProperty.call(ATLAS,editingExId))return;
 const id=editingExId;
 const tile=document.createElement('button');tile.type='button';tile.className='du-parchment-tile';
 tile.setAttribute('aria-label','Открыть энциклопедический лист: '+NAMES[id]);
 const img=document.createElement('img');img.src=ATLAS[id];img.alt='Атлас ДаВинчи: '+NAMES[id]+' на пергаменте';
 const label=document.createElement('span');label.textContent='Атлас ДаВинчи · '+NAMES[id].toLowerCase();
 tile.append(img,label);tile.addEventListener('click',()=>show(id));grid.prepend(tile);
};
const viewer=document.createElement('div');viewer.className='du-parchment-view';viewer.id='duParchmentViewer';
viewer.setAttribute('role','dialog');viewer.setAttribute('aria-modal','true');viewer.setAttribute('aria-label','Энциклопедический атлас ДаВинчи');
const close=document.createElement('button');close.type='button';close.className='du-parchment-close';close.textContent='×';close.setAttribute('aria-label','Закрыть');
const picture=document.createElement('img');picture.alt='Энциклопедический лист ДаВинчи';
viewer.append(close,picture);document.body.append(viewer);
function show(id){picture.src=ATLAS[id];picture.alt='Энциклопедический лист: '+NAMES[id];viewer.classList.add('on');close.focus()}
function hide(){viewer.classList.remove('on');picture.removeAttribute('src')}
close.addEventListener('click',hide);
viewer.addEventListener('click',e=>{if(e.target===viewer)hide()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&viewer.classList.contains('on'))hide()});
})();
